def round_revise_artifact_excluded(name: str) -> bool:
    suffixes = (
        "-output.txt",
        "-output-candidate.patch",
        ".done",
        ".dirty-tree",
        ".meta",
        ".prompt",
        ".sidecar",
        ".sidecar.history",
        ".events.jsonl",
        ".events.history",
        ".untracked-baseline",
        ".diag",
